字符序列用先序表示二叉树，点号 . 表示空孩子。序列是完整合法编码；根深度为0。程序的三个输出整数分别是多少？按输出顺序填三空。

```cpp
#include <iostream>
#include <string>
int leafDepthSum = 0;
int readTree(const std::string& s, int& p, int depth) {
    char c = s[p];
    ++p;
    if (c == '.') {
        return 0;
    }
    int left = readTree(s, p, depth + 1);
    int right = readTree(s, p, depth + 1);
    if (left == 0 && right == 0) {
        leafDepthSum += depth;
    }
    return 1 + left + right;
}
int main() {
    std::string s = "AB..CD..E..";
    int p = 0;
    int nodes = readTree(s, p, 0);
    std::cout << nodes << ' ' << leafDepthSum << ' ' << p << '\n';
}
```

