rotateLeft 将指定窗口循环左移一位，并把移动后的首元素加到引用参数 total。两个窗口位于同一数组中。程序输出的两个整数分别是多少？

```cpp
#include <iostream>
void rotateLeft(int* p, int n, int& total) {
    int first = p[0];
    for (int i = 0; i + 1 < n; ++i) {
        p[i] = p[i + 1];
    }
    p[n - 1] = first;
    total += p[0];
}
int weighted(const int* a, int n) {
    int result = 0;
    for (int i = 0; i < n; ++i) {
        result += (i + 1) * a[i];
    }
    return result;
}
int main() {
    int a[] = {2, 4, 6, 8, 10};
    int total = 0;
    rotateLeft(a + 1, 3, total);
    rotateLeft(a, 4, total);
    std::cout << total << ' ' << weighted(a, 5) << '\n';
}
```

