下列左右孩子下标数组描述一棵根为0的二叉树，−1表示无孩子。程序输出什么？按输出顺序填两空。

```cpp
#include <iostream>
#include <queue>
#include <algorithm>
int main() {
    const int left[] = {1, 3, -1, -1, -1, 6, -1};
    const int right[] = {2, 4, 5, -1, -1, -1, -1};
    const int value[] = {4, 2, 7, 5, 1, 3, 6};
    std::queue<int> q;
    q.push(0);
    int maxWidth = 0, leafSum = 0;
    while (!q.empty()) {
        int count = static_cast<int>(q.size());
        maxWidth = std::max(maxWidth, count);
        for (int i = 0; i < count; ++i) {
            int u = q.front();
            q.pop();
            if (left[u] == -1 && right[u] == -1) {
                leafSum += value[u];
            }
            if (left[u] != -1) q.push(left[u]);
            if (right[u] != -1) q.push(right[u]);
        }
    }
    std::cout << maxWidth << ' ' << leafSum << '\n';
}
```

